package org.sormus.downloads;
import android.content.Context;import android.content.SharedPreferences;import org.json.JSONObject;import java.net.HttpURLConnection;import java.net.URL;import java.io.*;
final class DownloadsApi {
 final SharedPreferences preferences;private final String fixedServer,fixedToken;DownloadsApi(Context c){this(c,null,null);}DownloadsApi(Context c,String server,String token){preferences=c.getSharedPreferences("connection",Context.MODE_PRIVATE);fixedServer=server;fixedToken=token;}
 HttpURLConnection connection(String method,String path)throws Exception{String origin=TransferProtocol.server(fixedServer==null?preferences.getString("server",""):fixedServer);if(!path.matches("/api/file-downloads/native/[a-z0-9/-]+"))throw new Exception("Invalid receiver operation.");HttpURLConnection c=(HttpURLConnection)new URL(origin+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(30000);c.setRequestMethod(method);c.setRequestProperty("X-Sormus-Downloads","1");String token=fixedToken==null?preferences.getString("token",""):fixedToken;if(!path.endsWith("/pair")){if(!token.matches("[a-f0-9]{64}"))throw new Exception("Pair this phone first.");c.setRequestProperty("Authorization","Bearer "+token);}return c;}
 JSONObject response(HttpURLConnection c)throws Exception{int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(in!=null)try(InputStream stream=in){byte[] b=new byte[8192];for(int n;(n=stream.read(b))!=-1;){if(bytes.size()+n>262144)throw new Exception("Receiver response is too large.");bytes.write(b,0,n);}}String text=new String(bytes.toByteArray(),"UTF-8");JSONObject out=new JSONObject(text.isEmpty()?"{}":text);if(code<200||code>=300)throw new Exception(out.optString("error","PC request failed ("+code+")."));return out;}
 JSONObject json(String method,String path,JSONObject body)throws Exception{HttpURLConnection c=connection(method,path);try{if(body!=null){byte[] b=body.toString().getBytes("UTF-8");c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);c.setFixedLengthStreamingMode(b.length);try(OutputStream out=c.getOutputStream()){out.write(b);}}return response(c);}finally{c.disconnect();}}
}
